<script setup>
import { computed, ref } from 'vue'
import e from '../data/report-evidence.json'
const metric=ref('psnr');const rows=computed(()=>e.fivek[metric.value]);const colors=['#0f62fe','#007d79','#6929c4'];const keys=['top1','best3','best5'];const names=['Top-1','Best-of-3','Best-of-5']
// Spaces keep UnoCSS variant-group expansion from matching arithmetic as CSS.
const y = value => metric.value === 'psnr'
  ? 260 - (value - 20) / 8 * 220
  : 260 - (value - 0.86) / 0.07 * 220
const ticks=computed(()=>metric.value==='psnr'?[20,22,24,26,28]:[.86,.88,.90,.92])
const format=v=>v.toFixed(metric.value==='psnr'?3:4)
</script>
<template><div class="stack"><div class="row spread"><div class="tabs" aria-label="Result metric"><button :aria-pressed="metric==='psnr'" @click.stop="metric='psnr'">PSNR (dB)</button><button :aria-pressed="metric==='ssim'" @click.stop="metric='ssim'">SSIM</button></div><p class="small muted">FiveK · report table / PPSD: 24.500 dB, SSIM 0.841*</p></div><div class="split wide-left grow"><svg viewBox="0 0 640 310" class="diagram" role="img" :aria-label="`FiveK ${metric} by expert, with offline Best-of-3 and Best-of-5`"><g v-for="t in ticks" :key="t"><line x1="55" x2="610" :y1="y(t)" :y2="y(t)" class="grid-lines"/><text x="44" :y="y(t)+5" text-anchor="end" class="svg-label">{{metric==='psnr'?t:t.toFixed(2)}}</text></g><rect x="552" y="30" width="64" height="235" fill="var(--pale)"/><line v-for="(expert,i) in e.fivek.experts" :key="expert" :x1="78+i*102" :x2="78+i*102" :y1="y(rows.top1[i])" :y2="y(rows.best5[i])" stroke="#b9c3cf" stroke-width="3"/><g v-for="(key,k) in keys" :key="key"><circle v-for="(v,i) in rows[key]" :key="i" :cx="78+i*102" :cy="y(v)" r="6" :fill="colors[k]"/></g><text v-for="(expert,i) in e.fivek.experts" :key="expert" :x="78+i*102" y="289" text-anchor="middle" class="svg-label">{{expert}}</text></svg><div><table class="evidence-table compact"><thead><tr><th>Expert</th><th v-for="name in names" :key="name" class="numeric">{{name}}</th></tr></thead><tbody><tr v-for="(expert,i) in e.fivek.experts" :key="expert" :class="{highlight:expert==='Mean'}"><td>{{expert}}</td><td v-for="key in keys" :key="key" class="numeric">{{format(rows[key][i])}}</td></tr></tbody></table></div></div><div class="legend"><span v-for="(name,i) in names" :key="name"><i :style="{background:colors[i]}"/>{{name}}{{i?' · oracle':''}}</span></div><p class="note">PSNR: archived 120-query diagnostic, not a verified final run. SSIM: report-only. *PPSD SSIM is inconsistent in the report; details are in the evidence index.</p></div></template>
